/** Render optional replay/determinism triage evidence for a repair prompt. */
function renderTriage(triage) {
  if (!triage) return '';
  const L = [];
  if (triage.nondeterministic) {
    L.push(`## Determinism flag

Two identical explorations of this module produced DIFFERENT state graphs —
the code is nondeterministic (Math.random / Date.now / retained mutable module
state). Remove the nondeterminism; every transition must depend only on
(state, action, data).`);
  }
  const replay = Array.isArray(triage.replay) ? triage.replay : [];
  if (replay.length) {
    const rows = replay.map((r) => {
      const whereBits = [r.scenario, r.index !== undefined ? `#${r.index}` : null].filter((x) => x !== null && x !== undefined && x !== '');
      const where = whereBits.length ? ` (${whereBits.join(' ')})` : '';
      const cls = r.classification ? ` classified '${r.classification}'` : '';
      const reason = r.rejectionReason !== undefined ? ` reason: ${JSON.stringify(r.rejectionReason)}` : '';
      const err = r.error ? ` error: ${r.error}` : '';
      return `- ${r.action}${where}: status ${r.status || 'fail'}${cls}${reason}${err}`;
    });
    L.push(`## Trace-replay triage (sam-tv classification of the failing windows)

'rejected' and 'identity-by-mutation' are the two GOOD no-op classes;
'unhandled' means the acceptor neither acted nor rejected — add an explicit
\`reject(reason)\` guard for that case. A 'rejected' window that still fails
disagrees with the trace: the guard fires when the implementation would act.

${rows.join('\n')}`);
  }
  return L.length ? `\n${L.join('\n\n')}\n` : '';
}

/** Stage 0: draft a contract.json from a free-form feature description. */
export function buildContractDraftPrompt(intent, { lang = 'javascript' } = {}) {
  return `You are drafting a Polygraph verification contract for a NEW piece of
stateful ${lang} code, before any of it is written. The contract is the design
spec: observable state, the action alphabet, and the rules a reader would need
to reproduce the behavior.

## Feature intent

${intent}

## What to produce

A single JSON object matching this shape:

{
  "lang": "${lang}",
  "stateKeys": [{ "name": "...", "type": "..." }, ...],
  "initState": { ... },
  "actions": { "ACTION_NAME": { "dataFields": { "field": "type note" } }, ... },
  "dataDomain": { "ACTION_NAME": { "field": ["concrete", "enumerable", "values"] } },
  "terminalStates": ["..."],
  "specialRules": [{ "name": "...", "note": "...", "whenState": "...", "whenAction": "..." }],
  "noOpRule": "An action that does not apply in the current state yields post == pre."
}

Rules:
  - stateKeys: the MINIMAL set of fields the behavior depends on. No display
    strings, timestamps, or IDs that don't drive transitions. The FIRST key is
    the primary control state (a small enum).
  - actions: the discrete events that step the machine. Model time and any
    external result (e.g. a payment processor's response) as fields in the
    action's data, never as something the code reads from a clock or an API.
  - dataDomain: EVERY data field declared in "actions" MUST have a matching
    entry here with its full set of concrete values (e.g. a result field with
    values 'ok'/'declined'/'error' -> ["ok","declined","error"]). This is not
    optional, twice over: (1) the model checker explores exactly this domain,
    and any action field missing from dataDomain is silently EXCLUDED from
    exploration — which would make bugs in that action's handling unreachable
    to find; (2) these domains are ALSO the generated module's declared intent
    domains — the exploration and transpilation sets rendered directly into
    the code's own manifest — so a missing entry blocks generation outright.
// Shared spec-loading + canonical-state helpers.
//
// ONE loader and ONE canonical stringify for the whole pipeline, so the replay
// half (sam-tv.mjs) and the model-checking half (check.mjs) can never
// disagree about which specs load or which states are equal. sam-tv.mjs (a
// standalone child process) imports the loader from here.
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { createRequire } from 'node:module';
import { Console } from 'node:console';
import vm from 'node:vm';
import { SAM_LIB_PATH, SAM_LIB_SPECIFIERS } from './sam-lib.mjs';

// Specs may console.log (LLM output often appends demo logging). Any stdout
// write from a spec would corrupt sam-tv.mjs's stdout JSON protocol, so the loader
// shadows `console` with a stderr-backed one via a compileFunction parameter —
// this covers module top-level logging AND calls inside init()/next(), because
// the parameter shadows the global for all code in the module.
export const stderrConsole = new Console({ stdout: process.stderr, stderr: process.stderr });

/**
 * Load a spec as a CommonJS module (module.exports = { init, next }) regardless
 * of the surrounding package's "type" field or the file extension (.js/.cjs).
 * Wraps the file in the standard CJS parameter list via vm.compileFunction —
 * the same mechanism Node's own CJS loader uses. ESM specs (.mjs / export
 * syntax) are NOT supported by this loader and will throw at compile time.
 */
export function loadSpec(specPath) {
  const abs = resolve(specPath);
  const code = readFileSync(abs, 'utf-8');
  const module = { exports: {} };
  const baseRequire = createRequire(abs);
  // Require-patch: a spec's require of the SAM library resolves to the VENDORED
  // 2.0.0-alpha bundle (scripts/vendor/sam-pattern.cjs), never to whatever
  // version happens to be installed near the spec — the v2 strict surface the
  // pipeline depends on is pinned by construction. All other specifiers pass
  // through untouched. (v2 is backward compatible, so legacy SAM specs loaded
  // through this loader keep working.)
  const require = Object.assign(
    (id) => (SAM_LIB_SPECIFIERS.includes(id) ? baseRequire(SAM_LIB_PATH) : baseRequire(id)),
    baseRequire
  );
  const compiled = vm.compileFunction(
    code,
    ['module', 'exports', 'require', '__filename', '__dirname', 'console'],
    { filename: abs }
  );
  compiled(module, module.exports, require, abs, dirname(abs), stderrConsole);
  return module.exports;
}

/**
 * Canonical stringify: key-order-insensitive. THE state-equality definition
 * for the whole pipeline (replay diff and checker visited-set alike) — two
 * states are equal iff stable(a) === stable(b).
 *
 * undefined, NaN and ±Infinity render as DISTINCT non-JSON sentinels, never
 * as 'null': trace windows come from JSON.parse and can only contain null,
 * so a spec that DROPPED a field (undefined) or computed NaN must NOT compare
 * equal to a trace value of null — that would score a failing window as a
 * pass.
 */
export function stable(v) {
  if (v === undefined) return 'undefined';
  if (typeof v === 'number' && !Number.isFinite(v)) return String(v); // NaN / Infinity / -Infinity
  if (v === null || typeof v !== 'object') return JSON.stringify(v);
  if (Array.isArray(v)) return '[' + v.map(stable).join(',') + ']';
  return '{' + Object.keys(v).sort().map((k) => JSON.stringify(k) + ':' + stable(v[k])).join(',') + '}';
}

/**
 * The action's declared data fields. Contracts in the wild use both
 * `dataFields:` (the schema's key) and `data:` — every consumer (prompt
 * builder, domain builder) MUST read them through this one accessor so the
 * prompt and the explored domain can never diverge.
 */
export function dataFieldsOf(actionSpec) {
  return actionSpec && actionSpec.dataFields ? actionSpec.dataFields : (actionSpec && actionSpec.data) || {};
}
// ONE resolution point for the SAM library (sam-lib / @cognitive-fab/sam-pattern).
//
// The v2 strict profile the plugin targets is 2.0.0-alpha.x, which is VENDORED
// at scripts/vendor/sam-pattern.cjs (see the provenance header there). Every
// consumer — the v2 replayer, the checker adapter, the spec loaders — resolves
// the library through this module (or through SAM_LIB_PATH for require-level
// patching), so switching to the published npm package later is a one-line
// change here.
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const HERE = dirname(fileURLToPath(import.meta.url));

/** Absolute path of the vendored CommonJS bundle (for require()-patch loaders). */
export const SAM_LIB_PATH = join(HERE, 'vendor', 'sam-pattern.cjs');

/** Module specifiers that must resolve to the vendored bundle inside specs. */
export const SAM_LIB_SPECIFIERS = ['@cognitive-fab/sam-pattern', 'sam-pattern', 'sam-lib'];

const requireCjs = createRequire(import.meta.url);

/** The vendored library itself ({ createInstance, SamSchemaError, ... }). */
export const samLib = requireCjs(SAM_LIB_PATH);
export const { createInstance } = samLib;

