  if (/^\{.*\}$/.test(arm)) return 'object';
  if (/^\[.*\]$/.test(arm) || /^[A-Za-z_$][\w<>,.\s]*\[\]$/.test(arm) || /^Array\s*<.*>$/.test(arm)) return 'array';
