// SAM v2 strict-profile spec of one order's stateful core (src/order.ts +
// the effect bookkeeping in src/host.impl.ts), with the payment provider as
// the COMPLETE intent. status 'none' stands for "never created".
'use strict';
const { createInstance } = require('sam-pattern');

const INITIAL_STATE = { status: 'none', items: 0, charges: 0, refunds: 0, pending: 0 };
const MAX_ITEMS = 3;

const instance = createInstance({ strict: true, hasAsyncActions: false });

const modelShape = {
  status: { type: 'string' },
  items: { type: 'number' },
  charges: { type: 'number' },
  refunds: { type: 'number' },
  pending: { type: 'number' },
};

const noData = { type: 'object', properties: {} };
const plain = () => ({ action: (data = {}) => ({ ...data }), schema: noData, domain: [{}] });

const actions = {
  CREATE: plain(),
  ADD_ITEM: plain(),
  REMOVE_ITEM: plain(),
  PLACE: plain(),
  SHIP: plain(),
  CANCEL: plain(),
  COMPLETE: {
    action: (data = {}) => ({ ...data }),
    schema: { type: 'object', properties: { outcome: { type: 'string', enum: ['ok', 'failed'] } }, required: ['outcome'] },
    domain: [{ outcome: 'ok' }, { outcome: 'failed' }],
  },
};

const acceptors = {
  CREATE: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'none') return reject('order exists');
    next.status = 'draft';
    unchanged('items', 'charges', 'refunds', 'pending');
  },
  ADD_ITEM: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'draft') return reject('not a draft');
    if (model.items >= MAX_ITEMS) return reject('draft full');
    next.items = model.items + 1;
    unchanged('status', 'charges', 'refunds', 'pending');
  },
  REMOVE_ITEM: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'draft') return reject('not a draft');
    if (model.items === 0) return reject('draft empty');
    next.items = model.items - 1;
    unchanged('status', 'charges', 'refunds', 'pending');
  },
  PLACE: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'draft') return reject('not a draft');
    if (model.items === 0) return reject('draft empty');
    next.status = 'placed';
    next.charges = model.charges + 1;
    next.pending = model.pending + 1;
    unchanged('items', 'refunds');
  },
  SHIP: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'paid') return reject('not paid');
    next.status = 'shipped';
    unchanged('items', 'charges', 'refunds', 'pending');
  },
  CANCEL: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status === 'draft') {
      next.status = 'cancelled';
      unchanged('items', 'charges', 'refunds', 'pending');
      return;
    }
    if (model.status === 'paid') {
      next.status = 'cancelled';
      next.refunds = model.refunds + 1;
      unchanged('items', 'charges', 'pending');
      return;
    }
    return reject(model.status === 'placed' ? 'payment in progress' : 'not cancellable');
  },
  // The provider answers a pending charge: the effect is consumed whatever the
  // order's status; only a placed order moves.
  COMPLETE: (model) => (p, { reject, next, unchanged }) => {
    if (model.pending === 0) return reject('no pending charge');
    next.pending = model.pending - 1;
    if (model.status === 'placed') next.status = p.outcome === 'ok' ? 'paid' : 'failed';
    else unchanged('status');
    unchanged('items', 'charges', 'refunds');
  },
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: { modelShape, actions, acceptors, reactors: [] },
});
const { intents } = control;

const init = () => setState(INITIAL_STATE);
const getState = () => instance({}).getState();
const setState = (snapshot) => instance({}).setState(snapshot);

const exported = {};
for (const name of Object.keys(actions)) exported[name] = (data = {}) => intents[name](data);

module.exports = { instance, init, actions: exported, getState, setState };

