// Differential replay: the host and the polygraph spec are driven with the same
// random command sequences on one order; every step's ok/refused verdict and
// observable state must agree.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import { loadSpec } from '../tools/polygraph/scripts/load-spec.mjs';
import samAdapter from '../tools/polygraph/scripts/sam-adapter.cjs';

const spec = loadSpec(new URL('../spec/order.spec.cjs', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const machine = samAdapter.makeSamAdapter(spec);

const CMDS = ['CREATE', 'ADD_ITEM', 'REMOVE_ITEM', 'PLACE', 'SHIP', 'CANCEL', 'COMPLETE'] as const;

let seed = 12345;
const rand = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };

test('host conforms to spec on random sequences', async () => {
  const seen = new Set<string>();
  for (let run = 0; run < 400; run++) {
    const h = await createHost();
    let state = machine.init();
    for (let i = 0; i < 12; i++) {
      const cmd = CMDS[rand(CMDS.length)];
      const outcome = rand(2) ? 'ok' : 'failed';
      let hostOk: boolean;
      switch (cmd) {
        case 'CREATE': hostOk = (await h.create('o')).ok; break;
        case 'ADD_ITEM': hostOk = (await h.addItem('o')).ok; break;
        case 'REMOVE_ITEM': hostOk = (await h.removeItem('o')).ok; break;
        case 'PLACE': hostOk = (await h.place('o')).ok; break;
        case 'SHIP': hostOk = (await h.ship('o')).ok; break;
        case 'CANCEL': hostOk = (await h.cancel('o')).ok; break;
        case 'COMPLETE': {
          const [e] = await h.pendingEffects();
          hostOk = !!e;
          if (e) await h.completeEffect(e.id, outcome);
          break;
        }
      }
      const r = machine.step(state, cmd, cmd === 'COMPLETE' ? { outcome } : {});
      state = r.state;
      seen.add(state.status);
      assert.equal(hostOk, r.verdict === 'accepted', `run ${run} step ${i} ${cmd}`);
      const v = await h.order('o');
      const pending = (await h.pendingEffects()).length;
      const hostState = v ? { ...v, pending } : { status: 'none', items: 0, charges: 0, refunds: 0, pending };
      assert.deepEqual(hostState, state, `run ${run} step ${i} ${cmd}`);
    }
  }
  assert.equal(seen.size, 7, `statuses visited: ${[...seen]}`);
});

