  | { type: 'addItem' }
  | { type: 'removeItem' }
  | { type: 'place' }
  | { type: 'ship' }
  | { type: 'cancel' }
  | { type: 'chargeResult'; outcome: 'ok' | 'failed' };

/** What a step asks the outside world to do. */
