import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const view = (status: string, items: number, charges = 0, refunds = 0) => ({ status, items, charges, refunds });

test('fresh system is empty', async () => {
  const h = await createHost();
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.pendingEffects(), []);
  for (const cmd of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'] as const) {
    assert.equal((await h[cmd]('a')).ok, false);
  }
});

test('create, duplicate refused', async () => {
  const h = await createHost();
  assert.deepEqual(await h.create('a'), { ok: true });
  assert.equal((await h.create('a')).ok, false);
  assert.deepEqual(await h.order('a'), view('draft', 0));
});

test('items bounded 0..3', async () => {
  const h = await createHost();
  await h.create('a');
  assert.equal((await h.removeItem('a')).ok, false);
  for (let i = 0; i < 3; i++) assert.equal((await h.addItem('a')).ok, true);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.removeItem('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('draft', 2));
});

test('happy path: place, pay, ship', async () => {
  const h = await createHost();
  await h.create('a');
  assert.equal((await h.place('a')).ok, false);
  await h.addItem('a'); await h.addItem('a');
  assert.equal((await h.place('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('placed', 2, 1));
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.deepEqual({ ...effs[0], id: undefined }, { id: undefined, from: 'a', kind: 'payment.charge', data: { amount: 2 } });
  assert.equal((await h.cancel('a')).ok, false);
  assert.equal((await h.ship('a')).ok, false);
  assert.equal((await h.addItem('a')).ok, false);
  assert.equal((await h.place('a')).ok, false);
  await h.completeEffect(effs[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.order('a'), view('paid', 2, 1));
  assert.equal((await h.ship('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('shipped', 2, 1));
  for (const cmd of ['addItem', 'removeItem', 'place', 'ship', 'cancel'] as const) {
    assert.equal((await h[cmd]('a')).ok, false);
  }
  await h.completeEffect(effs[0].id, 'failed');
  assert.deepEqual(await h.order('a'), view('shipped', 2, 1));
});

const ALL = ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'] as const;

test('first failed charge declines; retry; second failure fails', async () => {
  const h = await createHost();
  await h.create('a'); await h.addItem('a'); await h.place('a');
  assert.equal((await h.retryPayment('a')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'failed');
  assert.deepEqual(await h.order('a'), view('declined', 1, 1));
  for (const cmd of ALL.filter((c) => c !== 'retryPayment')) assert.equal((await h[cmd]('a')).ok, false, cmd);
  assert.deepEqual(await h.order('a'), view('declined', 1, 1));
  assert.equal((await h.retryPayment('a')).ok, true);
  assert.deepEqual(await h.order('a'), view('placed', 1, 2));
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 1);
  assert.notEqual(effs[0].id, e.id);
  assert.deepEqual([effs[0].kind, effs[0].from, effs[0].data], ['payment.charge', 'a', { amount: 1 }]);
  assert.equal((await h.retryPayment('a')).ok, false);
  await h.completeEffect(effs[0].id, 'failed');
  assert.deepEqual(await h.order('a'), view('failed', 1, 2));
  for (const cmd of ALL) assert.equal((await h[cmd]('a')).ok, false, cmd);
});

test('retry succeeds, then ship or cancel with refund', async () => {
  const h = await createHost();
  for (const id of ['s', 'c']) {
    await h.create(id); await h.addItem(id); await h.addItem(id); await h.place(id);
    await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
    await h.retryPayment(id);
    await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
    assert.deepEqual(await h.order(id), view('paid', 2, 2));
  }
  assert.equal((await h.ship('s')).ok, true);
  assert.deepEqual(await h.order('s'), view('shipped', 2, 2));
