  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.cancel('p')).ok, true);
  assert.deepEqual(await h.order('p'), view('cancelled', 1, 1, 1));
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.ship('p')).ok, false);
});

test('effects per order are independent', async () => {
  const h = await createHost();
  for (const id of ['a', 'b']) { await h.create(id); await h.addItem(id); await h.place(id); }
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 2);
