      if (o.status !== 'placed') return refuse(`order is ${o.status}, not placed`);
      // A first declined charge may be retried once; a second one is final.
      const status = a.outcome === 'ok' ? 'paid' : o.charges < MAX_CHARGES ? 'declined' : 'failed';
