// the effect bookkeeping in src/host.impl.ts), with the payment provider as
// the COMPLETE intent. status 'none' stands for "never created".
'use strict';
const { createInstance } = require('sam-pattern');

// taken is a ghost: how many charges went through (money actually taken). The
// host does not expose it; the invariants use it to state the money rules.
const INITIAL_STATE = { status: 'none', items: 0, charges: 0, refunds: 0, pending: 0, taken: 0 };
const MAX_ITEMS = 3;
const MAX_CHARGES = 2;

const instance = createInstance({ strict: true, hasAsyncActions: false });

const modelShape = {
  status: { type: 'string' },
  items: { type: 'number' },
  charges: { type: 'number' },
  refunds: { type: 'number' },
  pending: { type: 'number' },
  taken: { type: 'number' },
  held: { type: 'boolean' },
};

const noData = { type: 'object', properties: {} };
const plain = () => ({ action: (data = {}) => ({ ...data }), schema: noData, domain: [{}] });

const actions = {
  CREATE: plain(),
  ADD_ITEM: plain(),
  REMOVE_ITEM: plain(),
  PLACE: plain(),
  SHIP: plain(),
  CANCEL: plain(),
  RETRY_PAYMENT: plain(),
  HOLD: plain(),
  RELEASE: plain(),
  COMPLETE: {
    action: (data = {}) => ({ ...data }),
    schema: { type: 'object', properties: { outcome: { type: 'string', enum: ['ok', 'failed'] } }, required: ['outcome'] },
    domain: [{ outcome: 'ok' }, { outcome: 'failed' }],
  },
};

const acceptors = {
  CREATE: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'none') return reject('order exists');
    next.status = 'draft';
    unchanged('items', 'charges', 'refunds', 'pending', 'taken', 'held');
  },
  ADD_ITEM: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'draft') return reject('not a draft');
    if (model.items >= MAX_ITEMS) return reject('draft full');
    next.items = model.items + 1;
    unchanged('status', 'charges', 'refunds', 'pending', 'taken', 'held');
  },
  REMOVE_ITEM: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'draft') return reject('not a draft');
    if (model.items === 0) return reject('draft empty');
    next.items = model.items - 1;
    unchanged('status', 'charges', 'refunds', 'pending', 'taken', 'held');
  },
  PLACE: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'draft') return reject('not a draft');
    if (model.items === 0) return reject('draft empty');
    next.status = 'placed';
    next.charges = model.charges + 1;
    next.pending = model.pending + 1;
    unchanged('items', 'refunds', 'taken', 'held');
  },
  SHIP: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'paid') return reject('not paid');
    if (model.held) return reject('held');
    next.status = 'shipped';
    unchanged('items', 'charges', 'refunds', 'pending', 'taken', 'held');
  },
  HOLD: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'paid') return reject('not paid');
    if (model.held) return reject('already held');
    next.held = true;
    unchanged('status', 'items', 'charges', 'refunds', 'pending', 'taken');
  },
  RELEASE: (model) => (_p, { reject, next, unchanged }) => {
    if (!model.held) return reject('not held');
    next.held = false;
    unchanged('status', 'items', 'charges', 'refunds', 'pending', 'taken');
  },
  CANCEL: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status === 'draft') {
      next.status = 'cancelled';
      unchanged('items', 'charges', 'refunds', 'pending', 'taken', 'held');
      return;
    }
    if (model.status === 'paid') {
      next.status = 'cancelled';
      next.refunds = model.refunds + 1;
      next.held = false;
      unchanged('items', 'charges', 'pending', 'taken');
      return;
    }
    if (model.status === 'placed') {
      next.status = 'cancelling';
      unchanged('items', 'charges', 'refunds', 'pending', 'taken', 'held');
      return;
    }
    return reject('not cancellable');
  },
  RETRY_PAYMENT: (model) => (_p, { reject, next, unchanged }) => {
    if (model.status !== 'declined') return reject('not declined');
    next.status = 'placed';
    next.charges = model.charges + 1;
    next.pending = model.pending + 1;
    unchanged('items', 'refunds', 'taken', 'held');
  },
  // The provider answers a pending charge: the effect is consumed whatever the
  // order's status; only a placed or cancelling order moves.
  COMPLETE: (model) => (p, { reject, next, unchanged }) => {
    if (model.pending === 0) return reject('no pending charge');
    next.pending = model.pending - 1;
    next.taken = model.taken + (p.outcome === 'ok' ? 1 : 0);
    unchanged('items', 'charges', 'held');
    if (model.status === 'cancelling') {
      next.status = 'cancelled';
      if (p.outcome === 'ok') next.refunds = model.refunds + 1;
      else unchanged('refunds');
      return;
    }
    if (model.status === 'placed') next.status = p.outcome === 'ok' ? 'paid' : model.charges < MAX_CHARGES ? 'declined' : 'failed';
    else unchanged('status');
    unchanged('refunds');
  },
};

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: { modelShape, actions, acceptors, reactors: [] },
});
const { intents } = control;

const init = () => setState(INITIAL_STATE);
const getState = () => instance({}).getState();
const setState = (snapshot) => instance({}).setState(snapshot);

const exported = {};
for (const name of Object.keys(actions)) exported[name] = (data = {}) => intents[name](data);

module.exports = { instance, init, actions: exported, getState, setState };

