import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const view = (status: string, items: number, charges = 0, refunds = 0) => ({ status, items, charges, refunds });

test('fresh system is empty', async () => {
  const h = await createHost();
  assert.equal(await h.order('a'), null);
  assert.deepEqual(await h.pendingEffects(), []);
  for (const cmd of ['addItem', 'removeItem', 'place', 'ship', 'cancel', 'retryPayment'] as const) {
    assert.equal((await h[cmd]('a')).ok, false);
