  for (const cmd of ALL) assert.equal((await h[cmd]('a')).ok, false, cmd);
});

test('retry succeeds, then ship or cancel with refund', async () => {
  const h = await createHost();
  for (const id of ['s', 'c']) {
    await h.create(id); await h.addItem(id); await h.addItem(id); await h.place(id);
    await h.completeEffect((await h.pendingEffects())[0].id, 'failed');
    await h.retryPayment(id);
    await h.completeEffect((await h.pendingEffects())[0].id, 'ok');
    assert.deepEqual(await h.order(id), view('paid', 2, 2));
  }
  assert.equal((await h.ship('s')).ok, true);
  assert.deepEqual(await h.order('s'), view('shipped', 2, 2));
  assert.equal((await h.cancel('c')).ok, true);
  assert.deepEqual(await h.order('c'), view('cancelled', 2, 2, 1));
});

test('cancel draft and paid', async () => {
  const h = await createHost();
  await h.create('d');
  assert.equal((await h.cancel('d')).ok, true);
  assert.deepEqual(await h.order('d'), view('cancelled', 0));
  assert.equal((await h.cancel('d')).ok, false);
  await h.create('p'); await h.addItem('p'); await h.place('p');
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.cancel('p')).ok, true);
  assert.deepEqual(await h.order('p'), view('cancelled', 1, 1, 1));
  assert.deepEqual(await h.pendingEffects(), []);
  assert.equal((await h.ship('p')).ok, false);
});

test('cancel while placed waits for the answer', async () => {
  const h = await createHost();
  for (const id of ['ok', 'ko', 'retry']) { await h.create(id); await h.addItem(id); await h.place(id); }
  // 'retry': decline first, retry, then cancel during the second charge.
  const r1 = (await h.pendingEffects()).find((e) => e.from === 'retry')!;
  await h.completeEffect(r1.id, 'failed');
  await h.retryPayment('retry');
  for (const id of ['ok', 'ko', 'retry']) {
    assert.deepEqual(await h.cancel(id), { ok: true });
    assert.equal((await h.order(id))!.status, 'cancelling');
    assert.equal((await h.order(id))!.refunds, 0);
    for (const cmd of ALL) assert.equal((await h[cmd](id)).ok, false, `${id} ${cmd}`);
  }
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 3);
  const of = (id: string) => effs.find((e) => e.from === id)!.id;
  await h.completeEffect(of('ok'), 'ok');
  await h.completeEffect(of('ko'), 'failed');
  await h.completeEffect(of('retry'), 'ok');
  assert.deepEqual(await h.order('ok'), view('cancelled', 1, 1, 1));
  assert.deepEqual(await h.order('ko'), view('cancelled', 1, 1, 0));
  assert.deepEqual(await h.order('retry'), view('cancelled', 1, 2, 1));
  assert.deepEqual(await h.pendingEffects(), []);
  for (const cmd of ALL) assert.equal((await h[cmd]('ok')).ok, false, cmd);
});

test('effects per order are independent', async () => {
  const h = await createHost();
  for (const id of ['a', 'b']) { await h.create(id); await h.addItem(id); await h.place(id); }
  const effs = await h.pendingEffects();
  assert.equal(effs.length, 2);
  const b = effs.find((e) => e.from === 'b')!;
  await h.completeEffect(b.id, 'ok');
  assert.equal((await h.order('b'))!.status, 'paid');
  assert.equal((await h.order('a'))!.status, 'placed');
});

